SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "徐有贞", "aliases": ["徐有貞"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，景泰8年（1457年）正月，徐有贞以兵部尚书兼翰林学士身份入阁。", "biography": null, "status": "draft", "id": "a2c2c258-40a6-5fa1-b82d-a741f40d91fb"}, {"name": "朱祁镇", "aliases": ["明英宗"], "era": "明", "birth_year": null, "death_year": null, "description": "明英宗，宣德10年（1435年）正月，朱祁镇即皇帝位。", "biography": null, "status": "draft", "id": "368e5a42-621f-5c8c-88c7-f59b8bb8a5cf"}, {"name": "李贤（明代内阁大学士）", "aliases": ["李賢"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，景泰8年（1457年）二月，李贤以礼部侍郎兼翰林学士身份入阁。", "biography": null, "status": "draft", "id": "71c72fee-17ca-51a3-9ba9-aefc6570bfb8"}, {"name": "许彬", "aliases": ["許彬"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，景泰8年（1457年）正月，许彬升任礼部右侍郎，兼翰林学士并入阁。", "biography": null, "status": "draft", "id": "a9df097f-7235-5c19-b28f-89082c141669"}, {"name": "岳正", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，景泰8年（1457年）六月，岳正以翰林院修撰身份入阁。", "biography": null, "status": "draft", "id": "131712c8-8c7a-560e-a9ac-613dc9307339"}, {"name": "彭时", "aliases": ["彭時"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，正統14年（1449年）八月，彭时以翰林修撰身份入阁。", "biography": null, "status": "draft", "id": "a42ac84b-3969-512b-b1c5-d8e41cbc0eda"}, {"name": "王振（明英宗朝宦官）", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "王振（明英宗朝宦官）掌管司礼监。", "biography": null, "status": "draft", "id": "b348fa2c-6cc7-57f7-9f9b-3198d1f7128a"}, {"name": "吴与弼", "aliases": ["吳與弼"], "era": "明", "birth_year": null, "death_year": null, "description": "吴与弼以处士身份受朝廷征召。", "biography": null, "status": "draft", "id": "9df7d216-a79f-5c66-936f-da73c1dbc51d"}, {"name": "朱文圭", "aliases": ["建庶人"], "era": "明", "birth_year": null, "death_year": null, "description": "朱文圭获释并安置在凤阳。", "biography": null, "status": "draft", "id": "55364a88-a4d6-55b4-a37b-5fa052f8f9e4"}, {"name": "朱瑛（明代武进伯）", "aliases": ["武進伯朱瑛"], "era": "明", "birth_year": null, "death_year": null, "description": "朱瑛（明代武进伯）以广西总兵官身份率部征讨。", "biography": null, "status": "draft", "id": "8219d0c0-8d2b-563d-a100-3fb6897fa589"}, {"name": "曹钦", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "明代起兵者。天顺5年（年号对照1461年），本表记录了曹钦的活动。", "biography": null, "status": "draft", "id": "4667ba2d-c9e8-5b4f-8a95-cb0080e144eb"}, {"name": "柳溥", "aliases": ["安遠侯柳溥"], "era": "明", "birth_year": null, "death_year": null, "description": "柳溥奉命统兵到甘、凉抵御孛来。", "biography": null, "status": "draft", "id": "e9af0404-e605-59de-a4ce-8bab14641a26"}, {"name": "孛来", "aliases": ["孛來"], "era": "明", "birth_year": null, "death_year": null, "description": "孛来率部进攻宁夏。", "biography": null, "status": "draft", "id": "002b89e8-be8d-5e7f-9365-e517b45d0c6d"}, {"name": "朱允炆", "aliases": ["明惠帝"], "era": "明", "birth_year": null, "death_year": null, "description": "明惠帝。洪武31年（年号对照1398年），本表记录了朱允炆的活动。", "biography": null, "status": "draft", "id": "76ea9485-acac-508c-a6ae-e2532462c03e"}]'::jsonb)
