"unknown", "location_note": null, "status": "draft", "id": "b7fbe6ef-1b06-5bb3-a1f8-864b444e7155"}, {"title": "许彬调任南京礼部左侍郎", "description": "景泰8年（1457年）七月，许彬调任南京礼部左侍郎。", "start_year": 1457, "end_year": 1457, "time_original": "景泰8年（1457年）七月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "0d07642f-a106-5726-b59d-4a7cface4eb5"}, {"title": "岳正调任广东钦州同知", "description": "景泰8年（1457年）七月，岳正调任广东钦州同知。", "start_year": 1457, "end_year": 1457, "time_original": "景泰8年（1457年）七月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "65641365-bda6-5248-ae40-0653ff6ffbf0"}, {"title": "岳正调任钦州后下狱，被发往边地戍守", "description": "天顺元年七月条记，岳正调任钦州同知后，不久被关入监狱，继而被发往边地戍守。", "start_year": 1457, "end_year": 1457, "time_original": "天顺元年七月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8c3b717a-5b1e-5439-b61e-52547c927b36"}, {"title": "明廷大赦天下", "description": "天顺元年七月癸酉，朝廷下令大赦。", "start_year": 1457, "end_year": 1457, "time_original": "天顺元年七月癸酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9409822b-6705-5e36-a455-96e348c8fd40"}, {"title": "明廷向各边镇军士发放赏赐", "description": "天顺元年七月辛卯，朝廷向各边镇的军士广发赏赐。", "start_year": 1457, "end_year": 1457, "time_original": "天顺元年七月辛卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1099d0ad-27c3-50c2-9845-9c60661d1df3"}, {"title": "明英宗因彗星屡见亲自祭告上帝", "description": "天顺元年八月甲午，本纪记彗星屡次出现，明英宗朱祁镇为此亲自向上帝祷告。", "start_year": 1457, "end_year": 1457, "time_original": "天顺元年八月甲午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a6e424ba-41d8-5a1e-9540-02a0077b4352"}, {"title": "彭时以太常寺少卿兼翰林院侍读身份重新入阁", "description": "景泰8年（1457年）九月，彭时以太常寺少卿兼翰林院侍读身份重新入阁。", "start_year": 1457, "end_year": 1457, "time_original": "景泰8年（1457年）九月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "6a5c763b-6265-5f61-8afb-5422c6d97134"}, {"title": "明英宗命祭葬王振并建立祠堂", "description": "天顺元年十月丁酉，明英宗命人为王振举行祭葬并立祠。本纪称祠名为“旌忠”，《王振传》作“精忠”。", "start_year": 1457, "end_year": 1457, "time_original": "天顺元年十月丁酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8dd12031-fc3a-554f-b97a-dab78a8faee0"}, {"title": "明英宗征召江西处士吴与弼", "description": "天顺元年十月壬寅，朝廷征召在江西居住的处士吴与弼。", "start_year": 1457, "end_year": 1457, "time_original": "天顺元年十月壬寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "460ea214-6a67-5bb3-b10d-ca79914d26b2"}, {"title": "明英宗释放朱文圭及家属，安置在凤阳", "description": "天顺元年十月丙辰，明英宗释放了建文帝幼子朱文圭及其家属，将他们安置在凤阳。", "start_year": 1457, "end_year": 1457, "time_original": "天顺元年十月丙辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "864e3763-f9c1-5af8-a843-c0cda08f8d4f"}, {"title": "朱瑛率军征讨田州起事者", "description": "天顺元年十一月甲戌，广西总兵官朱瑛率军征讨田州反抗明廷的武装。", "start_year": 1457, "end_year": 1457, "time_original": "天顺元年十一月甲戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c4a202a6-661b-5786-aa15-6357da92532a"}, {"title": "明廷豁免山东灾区夏税", "description": "天顺元年十一月己丑，朝廷免除山东受灾地区应缴的夏税。", "start_year": 1457, "end_year": 1457, "time_original": "天顺元年十一月己丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7292c9b6-599a-5ea2-969a-f77061cbde09"}, {"title": "曹钦获封昭武伯", "description": "天顺元年十二月壬辰，朝廷封曹钦为昭武伯。", "start_year": 1457, "end_year": 1457, "time_original": "天顺元年十二月壬辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "073ac133-441b-53c7-8a70-348209a2840d"}, {"title": "柳溥奉命任总兵官，在甘州、凉州抵御孛来", "description": "天顺元年十二月辛丑，明廷任命安远侯柳溥为总兵官，令他在甘州、凉州一带抵御孛来所部。", "start_year": 1458, "end_year": 1458, "time_original": "天顺元年十二月辛丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "292b8e8d-be0a-5088-ac74-dda202eda0f0"}, {"title": "本纪汇记天顺元年多地入贡", "description": "天顺元年，琉球中山、安南、暹罗、占城、哈密和乌斯藏入贡。 按原历纪年，事情发生在公元1457至1458年之间。", "start_year": null, "end_year": null, "time_original": "天顺元年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8eaeab9d-1778-582a-a30e-db87cda1662f"}]'::jsonb)
