INSERT INTO public.fact_claim (id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status)
SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "person", "field_path": "description", "claim_text": "徐有贞再次被关押，后被放逐到金齿。", "citation": "《明史》卷12·本纪第十二·英宗后纪·mingshi-2f603db3d81e-p001720；天顺元年七月", "note": "原文：秋七月乙丑，復下徐有貞於獄。丙寅，承天門災。丁卯，躬禱於南郊。戊辰，敕修省。庚午，李賢復入閣。改許彬南京禮部侍郎。辛未，出岳正為欽州同知，尋下獄，謫戍。癸酉，大赦。癸未，放徐有貞於金齒；核对说明：按该段身份、官职、人物关系和相邻记载对照规范人物。原字保存在引文中。", "status": "draft", "id": "9554b67c-9584-505f-a2a4-0eb146747811", "subject_id": "a2c2c258-40a6-5fa1-b82d-a741f40d91fb", "source_id": "209a2064-96ff-509a-8474-a739f85f2234"}, {"subject_table": "event", "field_path": "description", "claim_text": "天顺元年七月乙丑，明廷再次将徐有贞关入监狱。癸未，朝廷将他放逐到金齿。", "citation": "《明史》卷12·本纪第十二·英宗后纪·mingshi-2f603db3d81e-p001720；天顺元年七月", "note": "原文：秋七月乙丑，復下徐有貞於獄。丙寅，承天門災。丁卯，躬禱於南郊。戊辰，敕修省。庚午，李賢復入閣。改許彬南京禮部侍郎。辛未，出岳正為欽州同知，尋下獄，謫戍。癸酉，大赦。癸未，放徐有貞於金齒；核对说明：本纪与宰辅年表同记徐有贞于天顺元年七月再次下狱并发金齿，记事两阶段分别是乙丑与癸未。", "status": "draft", "id": "5e4ad2a4-8782-5fa6-b13d-66dce5bce1e1", "subject_id": "851c24d8-dba7-54fe-8844-47f6ff218eaa", "source_id": "209a2064-96ff-509a-8474-a739f85f2234"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "原历天顺元年七月。DDBC历表换算所据为1457-07-30至1457-08-28，据此核对公元发生年份。", "citation": "《明史》卷12·本纪第十二·英宗后纪·mingshi-2f603db3d81e-p001720；天顺元年七月", "note": "原文：秋七月乙丑，復下徐有貞於獄。丙寅，承天門災。丁卯，躬禱於南郊。戊辰，敕修省。庚午，李賢復入閣。改許彬南京禮部侍郎。辛未，出岳正為欽州同知，尋下獄，謫戍。癸酉，大赦。癸未，放徐有貞於金齒；核对说明：本纪与宰辅年表同记徐有贞于天顺元年七月再次下狱并发金齿，记事两阶段分别是乙丑与癸未。", "status": "draft", "id": "66081f43-7d4c-56a3-b747-83992b97c7a9", "subject_id": "851c24d8-dba7-54fe-8844-47f6ff218eaa", "source_id": "209a2064-96ff-509a-8474-a739f85f2234"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "再次被关押，后被放逐到金齿", "citation": "《明史》卷12·本纪第十二·英宗后纪·mingshi-2f603db3d81e-p001720；天顺元年七月", "note": "原文：秋七月乙丑，復下徐有貞於獄。丙寅，承天門災。丁卯，躬禱於南郊。戊辰，敕修省。庚午，李賢復入閣。改許彬南京禮部侍郎。辛未，出岳正為欽州同知，尋下獄，謫戍。癸酉，大赦。癸未，放徐有貞於金齒；核对说明：只采用本段明确参与者和行动角色，既有连接按稳定编号复用。", "status": "draft", "id": "27de9d5